def is_sum_of_two_triangular_numbers(n):
    # Generate all triangular numbers up to sqrt(2*n)
    max_k = int((2 * n) ** 0.5)
    triangular_numbers = [k * (k + 1) // 2 for k in range(1, max_k + 1)]

    # Check if any two triangular numbers add up to n
    for i in range(len(triangular_numbers)):
        for j in range(i, len(triangular_numbers)):
            if triangular_numbers[i] + triangular_numbers[j] == n:
                return True

    return False

# Read input
