def find_coin_order(results):
    # Create a dictionary to store the weight relationships between coins
    weight_map = {}

    # Iterate through each result and update the weight map
    for result in results:
        coin1, relation, coin2 = result.split()
        if relation == '<':
            weight_map[coin1] = -1
            weight_map[coin2] = 1
        elif relation == '>':
            weight_map[coin1] = 1
            weight_map[coin2] = -1

    # Determine the order of coins based on the weight relationships
    order = []
    visited = set()

    def dfs(coin):
        if coin in visited:
            return
        visited.add(coin)
        for neighbor, weight in weight_map.items():
            if weight > 0 and neighbor != coin:
                dfs(neighbor)
        order.append(coin)

    for coin in weight_map.keys():
        if coin not in visited:
            dfs(coin)

    # Reverse the order to get the correct coin sequence
    return ''.join(order[::-1])

# Read input from standard input
results = [input().strip() for _ in range(3)]

# Find the coin order and print the result
print(find_coin_order(results))
