def min_perimeter(N):
    # If N is odd, the perimeter is 2 * (N + 1)
    if N % 2 == 1:
        return 2 * (N + 1)
    # If N is even, the perimeter is 2 * (N - 2) + 2
    else:
        return 2 * (N - 2) + 2

