def count_23_integers(l, r):
    def sieve(n):
        primes = [True] * (n + 1)
        p = 2
        while (p * p <= n):
            if (primes[p] == True):
                for i in range(p * p, n + 1, p):
                    primes[i] = False
            p += 1
        return [i for i in range(2, n) if primes[i]]

    primes = sieve(r)
    count = 0
    for p in primes:
        if p > r // 2:
            break
        count += (r // p - l // p + 1)
    return count

# Example usage
print(count_23_integers(1, 10))  # Output: 7
print(count_23_integers(100, 200))  # Output: 5
print(count_23_integers(1, 2000000000))  # Output: 326
```
